<template><div class="page"><div class="head"><div><span>PHM SECURITY / ACCESS CONTROL</span><h2>用户与权限</h2><p>管理员创建查看者账号，并按角色控制数据访问范围。</p></div><el-button @click="load" :loading="loading">刷新</el-button></div><el-card shadow="never" class="profile"><b>当前会话</b><span v-if="profile">{{profile.username}} · {{roleLabel(profile.role)}}</span><el-tag v-if="profile" type="success">{{profile.permissions.length}} 项权限</el-tag><el-alert v-else type="warning" title="未登录或会话已过期，请先登录" :closable="false"/></el-card><el-card v-if="profile?.role==='admin'" shadow="never" class="create"><template #header><b>创建查看者账号</b></template><el-form :model="form" :rules="rules" ref="formRef" label-width="100px" inline><el-form-item label="查看者ID" prop="username"><el-input v-model="form.username" placeholder="输入登录ID"/></el-form-item><el-form-item label="登录密码" prop="password"><el-input v-model="form.password" type="password" show-password placeholder="至少6位"/></el-form-item><el-form-item label="确认密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password placeholder="再次输入密码"/></el-form-item><el-form-item><el-button type="primary" :loading="creating" @click="createViewer">注册查看者</el-button></el-form-item></el-form></el-card><el-card shadow="never"><template #header><b>角色权限目录</b></template><el-table :data="roles" stripe><el-table-column prop="key" label="角色" width="130"><template #default="s">{{roleLabel(s.row.key)}}</template></el-table-column><el-table-column label="可执行权限"><template #default="s"><el-tag v-for="x in s.row.permissions" :key="x" size="small" effect="plain">{{permissionLabel(x)}}</el-tag></template></el-table-column></el-table></el-card><el-card shadow="never" class="notice"><b>权限说明</b><p>管理员可以创建查看者账号；查看者登录后只能浏览数据、仿真目录和分析结果，不能修改系统配置。</p></el-card></div></template>
<script setup>import{ref,onMounted}from'vue';import api from'../api';import{ElMessage}from'element-plus';const profile=ref(null),roles=ref([]),loading=ref(false),creating=ref(false),formRef=ref(),form=ref({username:'',password:'',confirm:''});const labels={admin:'管理员',viewer:'查看者',view:'查看数据',manage_users:'管理用户',manage_structure:'维护结构',submit_simulation:'提交仿真',run_analysis:'执行分析',publish:'发布结果'};const roleLabel=x=>labels[x]||x,permissionLabel=x=>labels[x]||x;const rules={username:[{required:true,message:'请输入查看者ID',trigger:'blur'}],password:[{required:true,min:6,message:'密码至少6位',trigger:'blur'}],confirm:[{required:true,validator:(r,v,cb)=>v!==form.value.password?cb(new Error('两次密码不一致')):cb(),trigger:'blur'}]};const load=async()=>{loading.value=true;try{profile.value=(await api.get('/permissions/profile/')).data;roles.value=(await api.get('/permissions/roles/')).data.roles}catch{profile.value=null;ElMessage.warning('请登录后查看权限信息')}finally{loading.value=false}};const createViewer=async()=>{await formRef.value.validate();creating.value=true;try{await api.post('/permissions/assign-role/',{username:form.value.username,password:form.value.password,role:'viewer'});ElMessage.success('查看者账号创建成功');form.value={username:'',password:'',confirm:''};formRef.value.resetFields()}catch(e){ElMessage.error(e.response?.data?.detail||'创建失败')}finally{creating.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.head span{font-size:11px;color:#287de6;font-weight:700;letter-spacing:1px}.head h2{margin:7px 0}.head p{margin:0;color:#8391a5}.el-card{border-radius:11px;margin-bottom:16px}.profile{display:flex;align-items:center;gap:18px}.profile span{color:#50647b}.el-tag{margin:3px}.create :deep(.el-form){display:flex;flex-wrap:wrap;align-items:center}.notice p{color:#65768c}</style>
